import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import type { ReactNode } from 'react';
import { AdminVideoUploadPage } from './AdminVideoUploadPage';
import { adminEndpointRequest } from './adminTransport';
import { adminWorkspace } from './adminWorkspace';
import { videoProject, videoProjectId, videoViewer, videoOperationId } from './videoUploadFixtures.testSupport';
import type { VideoProject } from './videoUploadApi';
import { ApiError } from '../../api/client';

vi.mock('./AdminAccess', () => ({
  AdminGate: ({ children }: { children: ReactNode }) => children,
  useAdminAccess: () => ({ active: true, available: true, viewerId: 'aaaaaaaaaaaaaaaaaaaaaaaa', epoch: 1, generation: 1 }),
  useAdminText: () => (key: string) => key, readCapabilities: vi.fn()
}));
vi.mock('./adminPageText', () => ({ useAdminDeliveryText: () => (key: string) => key }));
vi.mock('./PublishedVideoProject', () => ({ default: ({ children }: { children?: ReactNode }) => <><h1>video.published</h1>{children}</> }));
vi.mock('./useAdminOnline', () => ({ useOnline: () => true }));
vi.mock('./adminTransport', () => ({ adminEndpointRequest: vi.fn(), ADMIN_IMPORT_RELOAD_REQUIRED: 'ADMIN_IMPORT_RELOAD_REQUIRED' }));

const guard = { viewerId: videoViewer, epoch: 1, generation: 1, authority: 1 };
let current: VideoProject, client: QueryClient;
const writes: { path: string; body: Record<string, unknown> }[] = [];
beforeEach(() => {
  adminWorkspace.reset(); writes.length = 0; current = videoProject();
  vi.spyOn(adminWorkspace, 'capture').mockReturnValue(guard);
  vi.spyOn(adminWorkspace, 'current').mockReturnValue(true);
  vi.spyOn(adminWorkspace, 'getSnapshot').mockReturnValue({ ...adminWorkspace.getSnapshot(), ...guard, authorized: true, mode: 'admin' });
  vi.mocked(adminEndpointRequest).mockImplementation(async (path, _schema, init) => {
    if (!init?.method || init.method === 'GET') return { schemaVersion: 1, item: current } as never;
    const body = typeof init.body === 'string' ? JSON.parse(init.body) : {};
    writes.push({ path, body });
    if (init.method === 'PATCH') current = { ...current, revision: current.revision + 1, draft: { ...current.draft, ...body.patch },
      publication: current.publication.state === 'failed' ? { ...current.publication, state: 'idle', operationId: null, issue: null } : current.publication };
    return { schemaVersion: 1, item: current, receipt: { operationId: body.operationId, revision: current.revision } } as never;
  });
  client = new QueryClient({ defaultOptions: { queries: { retry: false, gcTime: 0 } } });
  client.setQueryData(['admin-capabilities', videoViewer, 1], { videoUploads: { enabled: true, maxFileBytes: 512 * 1024 ** 2, acceptedExtensions: ['mp4', 'mov', 'm4v'] } });
});
afterEach(() => { cleanup(); client.clear(); vi.restoreAllMocks(); });
function mount(projectId: string | null = videoProjectId) {
  render(<QueryClientProvider client={client}><MemoryRouter><AdminVideoUploadPage projectId={projectId ?? undefined} /></MemoryRouter></QueryClientProvider>);
}

test('self attribution publishes independently through a separate captured confirmation', async () => {
  mount(); await screen.findByDisplayValue('Synthetic Video');
  expect(writes).toEqual([]); fireEvent.click(screen.getByRole('button', { name: 'video.review' }));
  const dialog = await screen.findByRole('dialog', { name: 'video.confirm' });
  expect(within(dialog).getByText('video.personal')).toBeInTheDocument();
  expect(within(dialog).getByText('video.no_album')).toBeInTheDocument();
  expect(writes).toEqual([]);
  fireEvent.click(within(dialog).getByRole('button', { name: 'video.confirm_publish' }));
  await waitFor(() => expect(writes).toHaveLength(1));
  expect(writes[0]).toEqual({ path: `/video-projects/${videoProjectId}/publish`, body: { expectedRevision: 3, approvalDigest: current.approvalDigest, operationId: expect.any(String) } });
  expect(writes.some(write => write.path.endsWith('/source'))).toBe(false);
});

test('an external revision invalidates an open publication confirmation', async () => {
  mount(); await screen.findByDisplayValue('Synthetic Video'); fireEvent.click(screen.getByRole('button', { name: 'video.review' }));
  const confirm = await screen.findByRole('button', { name: 'video.confirm_publish' }); expect(confirm).toBeEnabled();
  await act(async () => { current = { ...current, revision: 4, approvalDigest: 'b'.repeat(64) }; client.setQueryData(['admin-video-project', videoViewer, 1, 1, videoProjectId], { schemaVersion: 1, item: current }); });
  await waitFor(() => expect(confirm).toBeDisabled()); expect(screen.getByText('video.stale')).toBeInTheDocument(); expect(writes).toEqual([]);
});

test('edited details save first and only their acknowledged server snapshot enters confirmation', async () => {
  mount(); await screen.findByDisplayValue('Synthetic Video');
  fireEvent.change(screen.getByRole('textbox', { name: /video.public_name/ }), { target: { value: 'Explicit byline' } });
  fireEvent.click(screen.getByRole('button', { name: 'video.review' }));
  const dialog = await screen.findByRole('dialog', { name: 'video.confirm' });
  expect(within(dialog).getByText('Explicit byline')).toBeInTheDocument();
  expect(writes).toHaveLength(1); expect(writes[0]).toMatchObject({ path: `/video-projects/${videoProjectId}`, body: { expectedRevision: 3, patch: { publicName: 'Explicit byline' } } });
});

test('unknown source outcomes reconcile the original operation without sending another source', async () => {
  current = { ...current, stage: 'upload', approvalDigest: null, source: { ...current.source, status: 'unknown' }, processing: { ...current.processing, state: 'idle', progress: null, facts: null } };
  mount(); await screen.findByRole('button', { name: 'video.reconcile' });
  expect(screen.getByRole('button', { name: 'video.reselect' })).toBeDisabled();
  fireEvent.click(screen.getByRole('button', { name: 'video.reconcile' }));
  await waitFor(() => expect(writes).toHaveLength(1));
  expect(writes[0]).toEqual({ path: `/video-projects/${videoProjectId}/source/reconcile`, body: { operationId: videoOperationId } });
});

test('failed processing retries server work without re-uploading the confirmed original', async () => {
  current = { ...current, stage: 'validate', approvalDigest: null, processing: { ...current.processing, state: 'failed', issue: 'processing_failed' } };
  mount(); fireEvent.click(await screen.findByRole('button', { name: 'video.processing_retry' }));
  await waitFor(() => expect(writes).toHaveLength(1));
  expect(writes[0]).toMatchObject({ path: `/video-projects/${videoProjectId}/processing/retry`, body: { expectedRevision: 3 } });
  expect(writes[0].body).not.toHaveProperty('file');
});

test('running processing shows its current extraction step and measured progress', async () => {
  current = { ...current, stage: 'validate', approvalDigest: null, processing: { ...current.processing, state: 'running', step: 'cover', progress: 75 } };
  mount();
  expect(await screen.findByText('video.step_cover')).toBeInTheDocument();
  expect(screen.getByRole('progressbar', { name: 'video.stage_2' })).toHaveAttribute('value', '75');
});

test.each(['ready', 'failed', 'queued', 'cancelled', 'published', 'frame'] as const)('%s processing does not present a retained extraction step as active work', async scenario => {
  current.processing = { ...current.processing, step: 'cover', progress: 100 };
  if (scenario === 'failed' || scenario === 'queued') current.processing.state = scenario;
  if (scenario === 'failed') current.processing.issue = 'processing_failed';
  if (scenario === 'cancelled') { current.stage = 'cancelled'; current.processing.state = 'running'; current.publication.state = 'cancelled'; }
  if (scenario === 'published') { current.stage = 'complete'; current.publication.state = 'complete'; }
  if (scenario === 'frame') current.frame.state = 'running';
  mount();
  if (scenario === 'published') await screen.findByRole('heading', { name: 'video.published' });
  else await screen.findByDisplayValue('Synthetic Video');
  expect(screen.queryByText('video.step_cover')).not.toBeInTheDocument();
  expect(screen.queryByRole('progressbar', { name: 'video.stage_2' })).not.toBeInTheDocument();
  if (scenario === 'failed') expect(screen.getByText('video.processing_issue_retry')).toBeInTheDocument();
  expect(writes).toEqual([]);
});

test('failed publication reuses its original approval operation without transmitting media', async () => {
  current = { ...current, stage: 'publish', publication: { ...current.publication, state: 'failed', operationId: videoOperationId, issue: 'storage_unknown' } };
  mount(); fireEvent.click(await screen.findByRole('button', { name: 'video.publication_retry' }));
  await waitFor(() => expect(writes).toHaveLength(1));
  expect(writes[0]).toEqual({ path: `/video-projects/${videoProjectId}/publication/retry`, body: { operationId: videoOperationId } });
});

test('completed tasks retain private cleanup recovery independently of current catalog cover editing', async () => {
  current.stage = 'complete'; current.publication = { ...current.publication, state: 'complete', cleanupPending: true };
  mount(); await screen.findByRole('heading', { name: 'video.published' });
  fireEvent.click(screen.getByRole('button', { name: 'video.cleanup_retry' }));
  await waitFor(() => expect(writes).toHaveLength(1));
  expect(writes[0].path).toBe(`/video-projects/${videoProjectId}/cleanup`);
  expect(writes[0].body.expectedRevision).toBe(current.revision);
  expect(writes[0].body).not.toHaveProperty('file');
});

test('an unavailable server never opens the native source picker or creates a private task', async () => {
  client.setQueryData(['admin-capabilities', videoViewer, 1], { videoUploads: { enabled: false, maxFileBytes: 512, acceptedExtensions: ['mp4', 'mov', 'm4v'] } });
  mount(null); await screen.findByText('video.unavailable');
  expect(screen.getByRole('button', { name: 'video.choose' })).toBeDisabled(); expect(writes).toEqual([]);
});

test.each(['reference_changed', 'approval_expired'])('%s opens a fresh approval through an empty draft save without changing metadata or uploading again', async issue => {
  current = { ...current, stage: 'publish', publication: { ...current.publication, state: 'failed', operationId: videoOperationId, issue } };
  mount(); fireEvent.click(await screen.findByRole('button', { name: 'video.review_again' }));
  await screen.findByRole('dialog', { name: 'video.confirm' });
  expect(writes).toHaveLength(1);
  expect(writes[0]).toMatchObject({ path: `/video-projects/${videoProjectId}`, body: { expectedRevision: 3, patch: {} } });
  expect(writes.some(write => /source|publication\/retry/.test(write.path))).toBe(false);
});

test('a restored receiving cover ingress reconciles the original cover operation before allowing new edits', async () => {
  current.ingress.cover = { operationId: videoOperationId, expectedRevision: 3, state: 'receiving', issue: null };
  mount(); const reconcile = await screen.findByRole('button', { name: 'video.cover_reconcile' });
  expect(screen.getByRole('textbox', { name: 'video.title' })).toBeDisabled();
  expect(screen.getByRole('button', { name: 'video.cover_upload' })).toBeDisabled();
  fireEvent.click(reconcile); await waitFor(() => expect(writes).toHaveLength(1));
  expect(writes[0]).toEqual({ path: `/video-projects/${videoProjectId}/covers/reconcile`, body: { operationId: videoOperationId } });
});

test('reconciliation 404 retains immutable cover bytes while the original request may still be receiving', async () => {
  const intent = { kind: 'covers', file: new Blob(['cover']), filename: 'cover.jpg', operationId: videoOperationId, expectedRevision: 3 };
  adminWorkspace.retain(`video-transfer:${videoProjectId}`, { running: false, intent, error: 'unknown' }, guard);
  vi.mocked(adminEndpointRequest).mockImplementation(async (path, _schema, init) => {
    if (init?.method === 'POST') throw new ApiError('not yet admitted', 'http', 404, 'ADMIN_VIDEO_OPERATION_NOT_FOUND');
    return { schemaVersion: 1, item: current } as never;
  });
  mount(); fireEvent.click(await screen.findByRole('button', { name: 'video.cover_reconcile' }));
  await waitFor(() => expect(screen.getByRole('button', { name: 'video.cover_reconcile' })).toBeEnabled());
  expect(adminWorkspace.buffer<{ intent: typeof intent }>(`video-transfer:${videoProjectId}`)?.intent).toEqual(intent);
  expect(screen.getByRole('button', { name: 'video.cover_upload' })).toBeDisabled(); expect(writes).toEqual([]);
});
